    const char* m_pData;
    explicit CCharString(const char* s) : m_pData(s) { ++g_live; }
    CCharString(const CCharString& other) : m_pData(other.m_pData) { ++g_live; }
    ~CCharString() { --g_live; }
};
static bool SameStr(const CCharString& a, const CCharString& b) { return a.m_pData == b.m_pData; }
class CScriptInfo;
struct CActivateQuestInfo {
    CCharString  QuestName;
    CScriptInfo* PScriptInfo;
    bool         GameScript;
    bool         LoadResources;
    CActivateQuestInfo(const char* n, CScriptInfo* s, bool g, bool l) : QuestName(n), PScriptInfo(s), GameScript(g), LoadResources(l) { }
};
typedef CActivateQuestInfo T;
static bool Same(const T& a, const T& b)
{
    return SameStr(a.QuestName, b.QuestName) && a.PScriptInfo == b.PScriptInfo && a.GameScript == b.GameScript && a.LoadResources == b.LoadResources;
}
